    /**
     * Graph Id
     */
    graph_id: string;
    /**
     * Name
     */
    name: string;
    /**
     * Nodes
     */
    nodes: Array<GraphNodeView>;
    /**
     * Retired
     */
    retired: boolean;
    /**
     * Sessions
     */
